{
  "name": "MDSnC 声光可调滤波器射频合成器",
  "name_en": "MDSnC AOTF RF Synthesizer",
  "manufacturer": "AA Opto-Electronic",
  "description": "MDSnC 是用于驱动声光可调滤波器（AOTF）的多通道射频合成器。它通过为各通道提供可调的射频频率和功率来控制 AOTF 的工作状态，常用于光谱、显微成像和激光实验中的波长选择与光强调节。",
  "description_en": "The MDSnC is a multi-channel RF synthesizer used to drive an acousto-optic tunable filter (AOTF). It controls AOTF operation by supplying adjustable RF frequency and power to individual channels, and is commonly used for wavelength selection and light intensity control in spectroscopy, microscopy, and laser experiments.",
  "tag_hints": [
    "AOTF control",
    "RF synthesizer",
    "multi-channel RF output",
    "wavelength selection",
    "optical modulation",
    "spectroscopy",
    "microscopy"
  ],
  "actions": [
    {
      "action_name": "auto-main_enabled",
      "description": "设置设备主输出启用状态。",
      "description_en": "Set the main output enable state."
    },
    {
      "action_name": "auto-enabled",
      "description": "设置指定通道的启用状态。",
      "description_en": "Set the enable state of a specified channel."
    },
    {
      "action_name": "auto-frequency",
      "description": "设置指定通道的射频频率。",
      "description_en": "Set the RF frequency for a specified channel."
    },
    {
      "action_name": "auto-powerdb",
      "description": "设置指定通道的射频功率（dB）。",
      "description_en": "Set the RF power for a specified channel in dB."
    },
    {
      "action_name": "auto-power",
      "description": "设置指定通道的射频功率（数字单位）。",
      "description_en": "Set the RF power for a specified channel in digital units."
    }
  ]
}

